[Fact]
public void Load_ignores_type_names_in_the_payload()
{
    var json = "{\"$type\":\"System.IO.FileInfo, System.IO.FileSystem\",\"Id\":9,\"Customer\":\"mallory\"}";
    var m = new OrderMessageReader().Load(json);
    Assert.IsType<OrderMessage>(m);
    Assert.Equal(9, m!.Id);
}
